// ─────────────────────────────────────────────────────────────────────────────
// Normalize WhatsApp Payload
// Parses the WhatsApp Cloud API webhook body and detects:
//   - Status-only callbacks (delivery/read receipts) → isStatusUpdate = true
//   - Real user messages → isStatusUpdate = false
// The downstream 'Is Status / Echo Update' guard routes accordingly.
// ─────────────────────────────────────────────────────────────────────────────

const body = $json.body || $json;
const entry = body && body.entry && body.entry[0];
const change = entry && entry.changes && entry.changes[0];
const value = change && change.value;
if (!value) return [];

const phoneNumberId = value.metadata && value.metadata.phone_number_id;
if (!phoneNumberId) return [];

// ── Detect Status-only callbacks (read receipts, delivery, failed) ─────────
// WhatsApp sends these WITHOUT a `messages` array — they only carry `statuses`.
const hasStatuses = value.statuses && value.statuses.length > 0;
const hasMessages = value.messages && value.messages.length > 0;

if (hasStatuses && !hasMessages) {
  // Pure status update (delivery/read receipt) — no user message to process
  const status = value.statuses[0];
  return [{
    json: {
      phoneNumberId,
      from: status.recipient_id || '',
      sessionId: 'wa_' + (status.recipient_id || ''),
      isStatusUpdate: true,
      statusType: status.status || 'unknown',
      userMessage: '',
      mediaType: 'text',
      mediaUrl: '',
      mediaId: '',
      profileName: ''
    }
  }];
}

if (!hasMessages) return [];

// ── Real inbound user message ─────────────────────────────────────────────────
const msg = value.messages[0];
const from = msg.from;
if (!from) return [];

const profileName =
  (value.contacts &&
    value.contacts[0] &&
    value.contacts[0].profile &&
    value.contacts[0].profile.name) || '';

// WhatsApp never sends a downloadable URL. It sends a media ID, which has to be
// exchanged for a short-lived URL using the integration's access token. That
// exchange needs a credential, so it happens in Build Brain Payload — not here.
let userMessage = '';
let mediaType = 'text';
let mediaUrl = '';
let mediaId = '';

if (msg.type === 'text') {
  userMessage = (msg.text && msg.text.body) || '';
} else if (msg.type === 'image') {
  // A caption is genuine customer text and is kept verbatim. With no caption,
  // userMessage stays empty and the Core Brain composes the message around the
  // image description instead of inventing one here.
  mediaType = 'image';
  mediaId = (msg.image && msg.image.id) || '';
  userMessage = (msg.image && msg.image.caption) || '';
} else if (msg.type === 'audio' || msg.type === 'voice') {
  mediaType = 'audio';
  mediaId = (msg.audio && msg.audio.id) || (msg.voice && msg.voice.id) || '';
} else if (msg.type === 'button' || msg.type === 'interactive') {
  const buttonText =
    (msg.button && msg.button.text) ||
    (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.title) ||
    (msg.interactive && msg.interactive.list_reply && msg.interactive.list_reply.title) ||
    '';
  // Product card taps arrive as a button or list id of ORDER:<productId>.
  // The marker tells the AI which product; the title stays readable in the inbox.
  const replyId =
    (msg.button && msg.button.payload) ||
    (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.id) ||
    (msg.interactive && msg.interactive.list_reply && msg.interactive.list_reply.id) ||
    '';
  userMessage = typeof replyId === 'string' && replyId.indexOf('ORDER:') === 0
    ? '[ORDER_CARD:' + replyId.slice(6) + '] ' + buttonText
    : buttonText;
} else {
  userMessage = '[Customer sent an unsupported message type on WhatsApp. Politely ask them to send text, a photo, or a voice note.]';
}

// A photo or voice note legitimately has no text, so emptiness only justifies
// dropping the item when there is no media to process either.
if (!userMessage && !mediaId) return [];

return [{
  json: {
    phoneNumberId,
    from,
    sessionId: 'wa_' + from,
    isStatusUpdate: false,
    statusType: '',
    userMessage,
    mediaType,
    mediaUrl,
    mediaId,
    // The typing indicator is attached to the customer's inbound message id.
    messageId: msg.id || '',
    profileName
  }
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Brain Payload (WhatsApp)
// Assembles the normalized context object for Core AI Brain.
//
// WhatsApp media arrives as an ID, never as a URL. The ID is exchanged here for
// the real one, because this node is the only one holding the access token:
//
//   GET /v20.0/{mediaId}?fields=url,mime_type  →  { url, mime_type }
//
// That URL expires within minutes and rejects unauthenticated requests, so the
// same token is forwarded as `mediaAuthHeader` for the Core Brain's download.
// ─────────────────────────────────────────────────────────────────────────────

const waPayload   = $('Normalize WhatsApp Payload').item.json;
const integration = $('Fetch Integration Secrets').item.json;

const chatbotId           = integration.chatbotId;
const accessToken         = (integration.accessToken || '').trim();
const sessionId           = waPayload.sessionId;
const from                = waPayload.from || '';
const profileName         = waPayload.profileName || 'WhatsApp User';
const originalMediaType   = waPayload.mediaType;

let userMessage     = waPayload.userMessage || '';
let mediaType       = waPayload.mediaType || 'text';
let mediaUrl        = waPayload.mediaUrl || '';
let mediaAuthHeader = '';

// ── Resolve the media ID into a usable, short-lived URL ──────────────────────
if (waPayload.mediaId && accessToken) {
  try {
    const media = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://graph.facebook.com/v20.0/' + waPayload.mediaId + '?fields=url,mime_type',
      headers: { Authorization: 'Bearer ' + accessToken },
      json: true
    });

    if (!media || !media.url) throw new Error('Meta returned no media URL');

    mediaUrl = media.url;
    mediaAuthHeader = 'Bearer ' + accessToken;
  } catch (err) {
    // A failed media lookup must never silence the customer. Downgrade to text
    // so the agent still answers instead of this execution dying here.
    console.error('[Build Brain Payload] WhatsApp media lookup failed:', err.message || err);
    mediaType = 'text';
    mediaUrl = '';
    userMessage =
      (userMessage ? userMessage + '\n' : '') +
      (originalMediaType === 'image'
        ? '[Customer sent a photo on WhatsApp that could not be loaded. Politely ask them to describe the product or send it again.]'
        : '[Customer sent a voice message on WhatsApp that could not be loaded. Politely ask them to type their question.]');
  }
} else if (waPayload.mediaId) {
  // Media arrived but the integration has no token to fetch it with.
  mediaType = 'text';
  mediaUrl = '';
  userMessage =
    (userMessage ? userMessage + '\n' : '') +
    '[Customer sent media on WhatsApp that could not be loaded. Politely ask them to describe it in text.]';
}

// Upsert payload passed to the Upsert Chat Session PostgreSQL node
const upsertPayload = {
  chatbotId,
  sessionId,
  guestName: profileName,
  profilePhoto: ''
};

return [{
  json: {
    chatbotId,
    sessionId,
    customerName: profileName,
    profilePhoto: null,
    userMessage,
    mediaType,
    mediaUrl,
    mediaAuthHeader,
    // Forwarded so Typing On can attach the indicator to the inbound message.
    messageId: waPayload.messageId || '',
    platform: 'whatsapp',
    _upsert: upsertPayload
  }
}];

// WhatsApp has no carousel in session messages, so the same information goes
// out as one interactive list (name + price + Order button) followed by one
// image message per product. The Cloud API caps rows at 10, row title at 24
// and row description at 72 characters.
const cards = $('Execute Core AI Brain').item.json.productCards || [];
const to = $('Normalize WhatsApp Payload').item.json.from || '';

const formatPrice = (card) => {
  const currency = String(card.currency || 'BDT');
  const amount = Number(card.price);
  return Number.isFinite(amount)
    ? (currency === 'BDT' ? '৳' : currency + ' ') + amount.toLocaleString('en-US')
    : String(card.price || '');
};

const rows = cards.slice(0, 10).map((card) => ({
  id: 'ORDER:' + card.productId,
  title: String(card.name || '').slice(0, 24),
  description: formatPrice(card).slice(0, 72)
}));

const messages = [];

if (rows.length > 0) {
  messages.push({
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: 'Tap the button to see our products and order.' },
      action: {
        button: '🛒 Order',
        sections: [{ title: 'Products', rows }]
      }
    }
  });
}

for (const card of cards.slice(0, 10)) {
  const imageUrl = String(card.imageUrl || '');
  if (!/^https:\/\//i.test(imageUrl)) continue;
  messages.push({
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'image',
    image: {
      link: imageUrl,
      caption: ('*' + String(card.name || '') + '*\n' + formatPrice(card)).slice(0, 1024)
    }
  });
}

return messages.map((message) => ({ json: { body: message } }));
